header_type_specs.canonical_declaration:
typedef struct coap_endpoint {
    struct sockaddr_storage addr;
    socklen_t addr_len;
} coap_endpoint_t;

typedef struct coap_udp_callbacks {
    coap_udp_on_datagram_fn on_datagram;
} coap_udp_callbacks_t;

typedef enum coap_type {
    COAP_TYPE_CON = 0,
    COAP_TYPE_NON = 1,
    COAP_TYPE_ACK = 2,
    COAP_TYPE_RST = 3,
} coap_type_t;

typedef enum coap_method {
    COAP_METHOD_GET = 1,
    COAP_METHOD_POST = 2,
    COAP_METHOD_PUT = 3,
    COAP_METHOD_DELETE = 4,
} coap_method_t;

typedef enum coap_option_number {
    COAP_OPT_URI_PATH = 11,
    COAP_OPT_CONTENT_FORMAT = 12,
    COAP_OPT_URI_QUERY = 15,
    COAP_OPT_ACCEPT = 17,
} coap_option_number_t;

typedef enum coap_content_format {
    COAP_FORMAT_TEXT_PLAIN = 0,
    COAP_FORMAT_LINK_FORMAT = 40,
    COAP_FORMAT_OCTET_STREAM = 42,
    COAP_FORMAT_APPLICATION_JSON = 50,
} coap_content_format_t;

typedef struct coap_option {
    uint16_t number;
    uint16_t length;
    uint8_t* value;
} coap_option_t;

typedef struct coap_message {
    uint8_t version;
    coap_type_t type;
    uint8_t code;
    uint16_t message_id;
    uint8_t token_len;
    uint8_t token[COAP_MAX_TOKEN_LEN];
    coap_option_t* options;
    size_t option_count;
    uint8_t* payload;
    size_t payload_len;
} coap_message_t;

typedef struct coap_bytes {
    uint8_t* data;
    size_t len;
} coap_bytes_t;

typedef enum coap_decode_status {
    COAP_DECODE_OK = 0,
    COAP_DECODE_INVALID = 1,
    COAP_DECODE_TRUNCATED = 2,
} coap_decode_status_t;

typedef struct coap_request {
    const coap_message_t* message;
    coap_method_t method;
    char* path;
    char* query;
    uint16_t content_format;
    bool has_content_format;
    uint16_t accept;
    bool has_accept;
} coap_request_t;
